import {escapeHtml as esc,icon} from './components.js';
import {macroValue} from './market-indicators.js';
import {marketPeriods,marketPoints,periodWindow,dateWindow} from './market-chart-model.js';
let active;
const time=at=>Number.isFinite(Date.parse(at))?new Date(at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',hour12:false})+' KST':'기준 시각 미제공';
export function openMarketChart({market,kind,id,name,item,feed}){
 active?.();const opener=document.activeElement,life=new AbortController(),dialog=document.createElement('dialog');
 const macro=kind==='macro',yieldRate=id==='KTB10Y',unit=macro?(yieldRate?'%':'원'):'pt',fmt=v=>Number.isFinite(v)?v.toLocaleString('ko-KR',{minimumFractionDigits:yieldRate?3:2,maximumFractionDigits:yieldRate?3:2}):'—';
 let lib,chart,line,average,points=[],feedData,period='3m',type='area',scale='price',resolution='daily',disposed=false,version=0,request;
 dialog.className='market-chart-dialog market-chart-workspace';dialog.setAttribute('aria-labelledby','market-chart-heading');
 dialog.innerHTML=`<header class="market-chart-header"><div><small>${esc(kind==='macro'?'환율·금리':kind==='futures'?'선물':'시장 지수')}</small><h2 id="market-chart-heading">${esc(name)}</h2></div><div class="market-chart-header-actions"><button data-mchart="fullscreen" aria-label="화면 가득 보기" aria-pressed="false">${icon('expand')}</button><button data-mchart="close" aria-label="차트 닫기">${icon('close')}</button></div></header>
 <div class="market-chart-body"><div class="market-chart-quote"><strong>${macro?macroValue(item):fmt(item?.value)+' '+unit}</strong><span>${esc(item?.closeLabel||'제공 시세')}</span><small>${esc(item?.asOfKind==='date'?item.asOf:time(item?.asOf))}</small></div>
 <div class="mc-toolbar"><div class="market-chart-periods" role="group" aria-label="차트 조회 기간">${marketPeriods.map(([key,label])=>`<button data-mchart="period" data-period="${key}">${label}</button>`).join('')}</div><select data-mc-type aria-label="지수 차트 모양"><option value="area">영역</option><option value="line">선</option></select><select data-mc-resolution aria-label="환율 차트 간격" hidden><option value="daily">일별</option><option value="intraday">1분</option></select><button data-mchart="settings" aria-expanded="false">차트 설정</button><button data-mchart="reset">원래 보기</button></div>
 <div class="mc-settings" hidden><label><input type="checkbox" data-mc-ma>20개 관측값 이동평균</label><label><input type="checkbox" data-mc-grid>격자</label><label>가격 축<select data-mc-scale><option value="price">${unit}</option>${yieldRate?'':'<option value="percent">기준값 대비 %</option>'}</select></label><form class="market-chart-dates"><label>시작<input type="date" name="from" required></label><label>종료<input type="date" name="to" required></label><button>기간 적용</button></form></div>
 <div class="mc-readout" aria-live="off"><span>날짜</span><strong>—</strong></div><p class="market-chart-message" role="status">과거 차트를 불러오고 있어요</p><div class="mc-canvas" tabindex="0" role="group" aria-label="가격 차트. 휠과 두 손가락으로 확대·축소, 드래그로 이동, 가격 축 드래그로 배율 조절"></div>
 <div class="mc-bottom"><div><button data-mchart="out" aria-label="차트 축소">−</button><button data-mchart="in" aria-label="차트 확대">＋</button><button data-mchart="latest">최신 구간</button></div><span class="mc-range"></span></div><div class="mc-stats"></div><p class="mc-source"></p><small class="mc-attribution"><a href="https://www.tradingview.com/" target="_blank" rel="noopener noreferrer">TradingView Lightweight Charts™</a> · Copyright (с) 2025 TradingView, Inc.</small></div>`;
 document.body.append(dialog);dialog.showModal();document.body.classList.add('modal-open');const $=s=>dialog.querySelector(s),canvas=$('.mc-canvas'),message=$('.market-chart-message'),form=$('form');
 function close(){if(disposed)return;disposed=true;life.abort();request?.abort();chart?.remove();dialog.remove();document.body.classList.remove('modal-open');opener?.isConnected&&opener.focus();removeEventListener('popstate',close);if(active===close)active=null;}
 active=close;addEventListener('popstate',close);dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('close',close);
 const chartTime=p=>feedData?.historyKind==='daily'?p.at.slice(0,10):Math.floor(p.t/1000);
 const dateText=p=>feedData?.historyKind==='daily'?p.at.slice(0,10):time(p.at);
 function inspect(index){const p=points[index];if(!p)return;const prev=points[index-1],diff=prev?p.value-prev.value:null;$('.mc-readout').innerHTML=`<span>${esc(dateText(p))}</span><strong>${fmt(p.value)} ${unit}</strong>${prev?`<small>직전 관측값 대비 ${diff>=0?'+':''}${yieldRate?fmt(diff*100)+'bp':fmt(diff)+' '+unit}</small>`:''}`;}
 function stats(range){if(!points.length)return;const first=Math.max(0,Math.ceil(range?.from??0)),last=Math.min(points.length-1,Math.floor(range?.to??points.length-1)),view=points.slice(first,last+1);if(!view.length)return;const a=view[0],b=view.at(-1),delta=b.value-a.value,ratio=a.value?(b.value/a.value-1)*100:null;
  $('.mc-range').textContent=`${dateText(a)} ~ ${dateText(b)}`;
  $('.mc-stats').innerHTML=`<span>선택 구간 ${yieldRate?'변화':'수익률'}<b>${yieldRate?(delta>=0?'+':'')+fmt(delta*100)+'bp':ratio===null?'—':(ratio>=0?'+':'')+fmt(ratio)+'%'}</b></span><span>최고<b>${fmt(Math.max(...view.map(p=>p.value)))} ${unit}</b></span><span>최저<b>${fmt(Math.min(...view.map(p=>p.value)))} ${unit}</b></span><span>관측값<b>${view.length}개</b></span>`;
 }
 function selectPeriod(){if(!chart||!points.length)return;const hours={ '1h':1,'4h':4 }[period],start=hours?Math.max(0,points.findIndex(p=>p.t>=points.at(-1).t-hours*3600000)):0,w=hours?{start,count:points.length-start}:periodWindow(points,period);chart.timeScale().setVisibleLogicalRange({from:w.start-.5,to:w.start+w.count-.5});chart.priceScale('right').applyOptions({autoScale:true});dialog.querySelectorAll('[data-period]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.period===period)));}
 function render(reset=true){if(!lib||!points.length)return;const previous=chart?.timeScale().getVisibleLogicalRange();chart?.remove();
  chart=lib.createChart(canvas,{autoSize:true,layout:{background:{type:'solid',color:'#fff'},textColor:'#6b7684',fontFamily:'Pretendard, sans-serif',fontSize:12,attributionLogo:true},grid:{vertLines:{visible:false},horzLines:{visible:$('[data-mc-grid]').checked,color:'#f0f2f5'}},rightPriceScale:{borderVisible:false,minimumWidth:82,mode:scale==='percent'?lib.PriceScaleMode.Percentage:lib.PriceScaleMode.Normal},timeScale:{borderColor:'#edf0f4',timeVisible:feedData.historyKind!=='daily',secondsVisible:false,lockVisibleTimeRangeOnResize:true},localization:{locale:'ko-KR',timeFormatter:t=>typeof t==='number'?time(new Date(t*1000).toISOString()):typeof t==='string'?t:`${t.year}-${t.month}-${t.day}`},crosshair:{mode:lib.CrosshairMode.Magnet},handleScroll:{pressedMouseMove:true,horzTouchDrag:true,vertTouchDrag:false,mouseWheel:true},handleScale:{mouseWheel:true,pinch:true,axisPressedMouseMove:{time:true,price:true}}});
  if(feedData.historyKind!=='daily')chart.applyOptions({timeScale:{tickMarkFormatter:t=>typeof t==='number'?new Date(t*1000).toLocaleTimeString('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false}):null}});
  const color=macro?'#61758c':Number.isFinite(item?.changePct)&&item.changePct<0?'#3479d4':'#d84b52';
  line=chart.addSeries(type==='area'?lib.AreaSeries:lib.LineSeries,{color,lineColor:color,topColor:color+'26',bottomColor:color+'00',lineWidth:2,priceLineVisible:false,priceFormat:{type:'custom',formatter:fmt,minMove:yieldRate?.001:.01}});line.setData(points.map(p=>({time:chartTime(p),value:p.value})));
  if($('[data-mc-ma]').checked){average=chart.addSeries(lib.LineSeries,{color:'#b7791f',lineWidth:2,lastValueVisible:false,priceLineVisible:false,title:'MA 20'});let sum=0;average.setData(points.map((p,i)=>{sum+=p.value;if(i>=20)sum-=points[i-20].value;return i>=19?{time:chartTime(p),value:sum/20}:{time:chartTime(p)};}));}
  chart.subscribeCrosshairMove(e=>{const t=typeof e.time==='object'?`${e.time.year}-${String(e.time.month).padStart(2,'0')}-${String(e.time.day).padStart(2,'0')}`:e.time;const i=points.findIndex(p=>chartTime(p)===t);inspect(i<0?points.length-1:i);});chart.timeScale().subscribeVisibleLogicalRangeChange(stats);
  if(reset||!previous)selectPeriod();else chart.timeScale().setVisibleLogicalRange(previous);inspect(points.length-1);
 }
 async function load(){const current=++version;request?.abort();request=new AbortController();message.textContent='과거 차트를 불러오고 있어요';canvas.setAttribute('aria-busy','true');
  try{const response=await fetch('/api/market-chart?'+new URLSearchParams({market,kind,id,resolution}),{signal:AbortSignal.any([life.signal,request.signal,AbortSignal.timeout(30000)])}),data=await response.json();if(disposed||current!==version)return;
   if(!response.ok)throw Error();feedData=data;points=marketPoints(data.points||[]);chart?.remove();chart=null;
   if(!points.length){canvas.hidden=true;message.textContent=data.message||'제공된 가격 이력이 없습니다.';$('.mc-readout').innerHTML='<strong>데이터 없음</strong>';$('.mc-stats').innerHTML='';return;}
   canvas.hidden=false;message.textContent=data.stale?'갱신 지연 · 마지막 정상 이력을 표시합니다.':'';$('[data-mc-resolution]').hidden=!data.supportsIntraday;
   const periods=resolution==='intraday'?[['1h','1시간'],['4h','4시간'],['all','전체']]:marketPeriods;if(!periods.some(([id])=>id===period))period=resolution==='intraday'?'4h':'3m';$('.market-chart-periods').innerHTML=periods.map(([key,label])=>`<button data-mchart="period" data-period="${key}">${label}</button>`).join('');
   $('.mc-source').textContent=[data.source||feed?.source,feedData.historyKind==='daily'?'일별 가격 · 분봉 자료 아님':(id==='USDKRW'&&resolution==='intraday'?'1분 가격 · 공급처 관측값':'장중 가격 · 공급처 관측값'),data.basis,data.asOf?'이력 기준 '+(feedData.historyKind==='daily'?data.asOf.slice(0,10):time(data.asOf)):null,data.syncedAt?'수집 '+time(data.syncedAt):null].filter(Boolean).join(' · ');
   const inputDay=p=>data.historyKind==='daily'?p.at.slice(0,10):new Date(p.t+9*3600000).toISOString().slice(0,10);form.elements.from.value=inputDay(points[0]);form.elements.to.value=inputDay(points.at(-1));
   lib??=await import('/vendor/lightweight-charts/lightweight-charts.mjs');if(disposed||current!==version)return;render();
  }catch(error){if(!disposed&&current===version&&error.name!=='AbortError'){message.textContent='차트를 불러오지 못했습니다. 다시 시도해 주세요.';canvas.hidden=true;}}
  finally{if(!disposed&&current===version)canvas.setAttribute('aria-busy','false');}
 }
 dialog.addEventListener('click',event=>{const b=event.target.closest('[data-mchart]');if(!b)return;const action=b.dataset.mchart;if(action==='close')return close();if(action==='fullscreen'){const full=dialog.classList.toggle('is-fullscreen');b.setAttribute('aria-pressed',String(full));return;}if(action==='settings'){$('.mc-settings').hidden=!$('.mc-settings').hidden;b.setAttribute('aria-expanded',String(!$('.mc-settings').hidden));return;}if(!chart)return;
  if(action==='period'){period=b.dataset.period;selectPeriod();}else if(action==='reset'){period=resolution==='intraday'?'4h':'3m';selectPeriod();}else{const r=chart.timeScale().getVisibleLogicalRange();if(!r)return;const width=r.to-r.from;if(action==='latest')chart.timeScale().setVisibleLogicalRange({from:points.length-width,to:points.length});else if(['in','out'].includes(action)){const mid=(r.from+r.to)/2,w=Math.max(3,width*(action==='in'?.75:1.333));chart.timeScale().setVisibleLogicalRange({from:mid-w/2,to:mid+w/2});}}
 },{signal:life.signal});
 dialog.addEventListener('change',event=>{const t=event.target;if(t.matches('[data-mc-resolution]')){resolution=t.value;return void load();}if(t.matches('[data-mc-type]'))type=t.value;else if(t.matches('[data-mc-scale]')){scale=t.value;const ma=$('[data-mc-ma]');ma.disabled=scale==='percent';ma.title=ma.disabled?'이동평균은 가격 축에서 표시합니다.':'';if(ma.disabled)ma.checked=false;}else if(!t.matches('[data-mc-grid],[data-mc-ma]'))return;render(false);},{signal:life.signal});
 form.addEventListener('submit',event=>{event.preventDefault();const dated=feedData?.historyKind==='daily'?points:points.map(p=>({...p,t:p.t+9*3600000})),w=dateWindow(dated,form.elements.from.value,form.elements.to.value);if(!w){message.textContent='선택 기간에 제공된 데이터가 없습니다.';return;}message.textContent='';chart?.timeScale().setVisibleLogicalRange({from:w.start-.5,to:w.start+w.count-.5});},{signal:life.signal});
 canvas.addEventListener('keydown',event=>{const r=chart?.timeScale().getVisibleLogicalRange();if(!r)return;if(['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();const move=(r.to-r.from)*.2*(event.key==='ArrowLeft'?-1:1);chart.timeScale().setVisibleLogicalRange({from:r.from+move,to:r.to+move});}if(['+','=','-','Home','End'].includes(event.key)){event.preventDefault();$(`[data-mchart="${event.key==='Home'?'reset':event.key==='End'?'latest':event.key==='-'?'out':'in'}"]`).click();}},{signal:life.signal});
 load();
}
